body.script:
document.addEventListener('DOMContentLoaded', function() {

    // ============================================================
    // TAB SWITCHING
    // ============================================================
    let attendanceLoaded = false;

    document.querySelectorAll('.tab-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
            const tabName = this.dataset.tab;
            switchTab(tabName);
        });
    });

    function switchTab(tabName) {
        // Toggle buttons
        document.querySelectorAll('.tab-btn').forEach(function(b) {
            b.classList.toggle('active', b.dataset.tab === tabName);
        });
        // Toggle panels
        document.querySelectorAll('.tab-panel').forEach(function(p) {
            p.classList.toggle('active', p.id === 'panel-' + tabName);
        });
        // Lazy load attendance data on first open
        if (tabName === 'gio-cong' && !attendanceLoaded) {
            loadAttendanceData(currentMonth, currentYear);
            attendanceLoaded = true;
        }
    }

    // ============================================================
    // ATTENDANCE DATA — FILTER INIT
    // ============================================================
    const now = new Date();
    let currentMonth = now.getMonth() + 1;
    let currentYear = now.getFullYear();

    // Populate year dropdown (current + 2 previous years)
    const yearSelect = document.getElementById('filter-year');
    for (let y = currentYear; y >= currentYear - 2; y--) {
        const opt = document.createElement('option');
        opt.value = y;
        opt.textContent = 'Năm ' + y;
        yearSelect.appendChild(opt);
    }

    // Set default month/year selects
    document.getElementById('filter-month').value = currentMonth;
    yearSelect.value = currentYear;

    // Filter change listeners (US2)
    document.getElementById('filter-month').addEventListener('change', function() {
        currentMonth = parseInt(this.value);
        attendanceLoaded = false;
        loadAttendanceData(currentMonth, currentYear);
        attendanceLoaded = true;
    });
    yearSelect.addEventListener('change', function() {
        currentYear = parseInt(this.value);
        attendanceLoaded = false;
        loadAttendanceData(currentMonth, currentYear);
        attendanceLoaded = true;
    });

    // ============================================================
    // LOAD ATTENDANCE DATA (lazy fetch)
    // ============================================================
    function loadAttendanceData(month, year) {
        document.getElementById('attendance-loading').style.display = 'flex';
        document.getElementById('attendance-empty').style.display = 'none';
        document.getElementById('attendance-table').style.display = 'none';

        fetch('/dang-ky-ca/gio-cong', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {month: month, year: year}
            })
        })
        .then(function(response) { return response.json(); })
        .then(function(data) {
            document.getElementById('attendance-loading').style.display = 'none';
            if (data.result && data.result.success) {
                renderAttendanceTable(data.result);
            } else {
                const msg = (data.result && data.result.message) || 'Lỗi không xác định';
                showAttendanceError(msg);
            }
        })
        .catch(function(err) {
            document.getElementById('attendance-loading').style.display = 'none';
            showAttendanceError('Lỗi kết nối: ' + err);
        });
    }

    // ============================================================
    // RENDER ATTENDANCE TABLE
    // ============================================================
    function renderAttendanceTable(data) {
        const tbody = document.getElementById('attendance-body');
        tbody.innerHTML = '';

        if (!data.records || data.records.length === 0) {
            document.getElementById('attendance-empty').style.display = 'block';
            document.getElementById('attendance-table').style.display = 'none';
            document.getElementById('attendance-total').textContent = '–';
            return;
        }

        data.records.forEach(function(rec) {
            const tr = document.createElement('tr');

            const checkOutDisplay = rec.check_out || 'Đang làm';

            // Build cells using textContent to prevent XSS
            const cells = [
                {text: rec.date, html: false},
                {text: rec.check_in, html: false},
                {text: rec.check_out, html: true, fallback: 'Đang làm'},
                {text: rec.worked_hours_display, html: false},
                {text: rec.check_in_status, html: false, cls: getStatusClass(rec.check_in_status)},
                {text: rec.check_out_status, html: false, cls: getStatusClass(rec.check_out_status)},
                {text: rec.salary_display + ' đ', html: false, cls: 'att-salary-cell'},
            ];

            cells.forEach(function(cell) {
                const td = document.createElement('td');
                if (cell.cls) td.className = cell.cls;
                if (cell.html && !cell.text) {
                    td.innerHTML = cell.fallback || '–';
                } else {
                    td.textContent = cell.text || '–';
                }
                tr.appendChild(td);
            });

            tbody.appendChild(tr);
        });

        // Update footer
        const totalEl = document.getElementById('attendance-total');
        totalEl.textContent = data.total_salary_display + ' đ';

        const badge = document.getElementById('provisional-badge');
        badge.style.display = data.is_provisional ? 'inline-block' : 'none';

        document.getElementById('attendance-table').style.display = 'table';
    }

    function getStatusClass(status) {
        if (!status || status === '–') return 'att-status-none';
        if (status.startsWith('Trễ')) return 'att-status-late';
        if (status.startsWith('Sớm')) return 'att-status-early';
        return 'att-status-ok';
    }

    function showAttendanceError(msg) {
        const empty = document.getElementById('attendance-empty');
        empty.querySelector('p').textContent = msg;
        empty.style.display = 'block';
    }

    // ============================================================
    // TAB 1: ĐĂNG KÝ CA (giữ nguyên logic cũ)
    // ============================================================
    let newSelections = [];

    document.querySelectorAll('#panel-dang-ky-ca .shift-cell').forEach(cell => {
        cell.addEventListener('click', function() {
            const date = this.dataset.date;
            const shiftId = this.dataset.shiftId;
            const isRegistered = this.dataset.registered === 'true';
            const state = this.dataset.state;

            if (state === 'confirmed') {
                return;
            }

            if (isRegistered && state === 'draft') {
                if (confirm('Bạn muốn hủy đăng ký ca này?')) {
                    removeRegistration(date, shiftId, this);
                }
            } else if (!isRegistered) {
                const index = newSelections.findIndex(s => s.date === date && s.shift_id === shiftId);

                if (index > -1) {
                    newSelections.splice(index, 1);
                    this.classList.remove('selected');
                } else {
                    newSelections.push({date: date, shift_id: shiftId});
                    this.classList.add('selected');
                }

                updateSelectionCount();
            }
        });
    });

    function updateSelectionCount() {
        document.getElementById('selectedCount').textContent = newSelections.length;
    }

    document.getElementById('btnSaveRegistration').addEventListener('click', function() {
        if (newSelections.length === 0) {
            alert('Vui lòng chọn ít nhất một ca!');
            return;
        }

        this.disabled = true;
        this.innerHTML = ' Đang lưu...';

        fetch('/dang-ky-ca/save', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {selections: newSelections}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                alert(data.result.message);
                location.reload();
            } else {
                alert('Lỗi: ' + (data.result ? data.result.message : 'Không xác định'));
                this.disabled = false;
                this.innerHTML = ' Lưu đăng ký';
            }
        })
        .catch(error => {
            alert('Lỗi kết nối: ' + error);
            this.disabled = false;
            this.innerHTML = ' Lưu đăng ký';
        });
    });

    function removeRegistration(date, shiftId, cell) {
        fetch('/dang-ky-ca/remove', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {date: date, shift_id: shiftId}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                cell.classList.remove('registered');
                cell.dataset.registered = 'false';
                cell.querySelector('i').className = 'fa fa-circle-o';
            } else {
                alert('Lỗi: ' + (data.result ? data.result.message : 'Không xác định'));
            }
        });
    }

}); // end DOMContentLoaded
